mod inflection;

use inflection::Inflector;
use std::io::Write;

fn main() {
    let args: Vec<Vec<u8>> = {
        #[cfg(unix)]
        {
            use std::os::unix::ffi::OsStringExt;
            std::env::args_os().skip(1).map(|a| a.into_vec()).collect()
        }
        #[cfg(not(unix))]
        {
            std::env::args().skip(1).map(|a| a.into_bytes()).collect()
        }
    };

    if args.is_empty() {
        return;
    }
    let w: &[u8] = &args[0];

    // Compute all 20 results before printing anything (mirrors C++).
    let results: Vec<Vec<u8>> = vec![
        Inflector::pluralize(w),
        Inflector::singularize(w),
        Inflector::camelize(w),
        Inflector::camelize_upper(w),
        Inflector::underscore(w),
        Inflector::classify(w),
        Inflector::tableize(w),
        Inflector::humanize(w),
        Inflector::titleize(w),
        Inflector::dasherize(w),
        Inflector::parameterize(w),
        {
            let mut s = b"A ".to_vec();
            s.extend_from_slice(w);
            s.extend_from_slice(b" Test");
            Inflector::parameterize(&s)
        },
        Inflector::upcase(w),
        Inflector::downcase(w),
        Inflector::capitalize(w),
        Inflector::decapitalize(w),
        Inflector::truncate(w, 5),
        {
            let mut s = b"Test::".to_vec();
            s.extend_from_slice(w);
            Inflector::demodulize(&s)
        },
        if Inflector::is_plural(w) { b"1".to_vec() } else { b"0".to_vec() },
        if Inflector::is_singular(w) { b"1".to_vec() } else { b"0".to_vec() },
    ];

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for r in &results {
        out.write_all(r).unwrap();
        out.write_all(b"\n").unwrap();
    }
    out.flush().unwrap();
}

//! Byte-oriented inflection library mirroring the C++ Inflector API.
//! All operations are on raw bytes with C-locale ASCII semantics.

pub struct Inflector;

const UNCOUNTABLES: [&[u8]; 10] = [
    b"equipment",
    b"information",
    b"rice",
    b"money",
    b"species",
    b"series",
    b"fish",
    b"sheep",
    b"jeans",
    b"police",
];

fn to_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - 32
    } else {
        b
    }
}

fn to_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b + 32
    } else {
        b
    }
}

/// C-locale isspace: space, \t, \n, \v, \f, \r.
fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0B | 0x0C | b'\r')
}

fn is_uncountable(w: &[u8]) -> bool {
    UNCOUNTABLES.iter().any(|u| *u == w)
}

impl Inflector {
    pub fn pluralize(w: &[u8]) -> Vec<u8> {
        if is_uncountable(w) {
            return w.to_vec();
        }
        let mut r = w.to_vec();
        r.push(b's');
        r
    }

    pub fn singularize(w: &[u8]) -> Vec<u8> {
        if is_uncountable(w) {
            return w.to_vec();
        }
        let n = w.len();

        // Rule 1: Y+"ses" -> Y + ("a" if Y=="analy") + "sis"
        for y in [
            &b"analy"[..],
            b"ba",
            b"diagno",
            b"parenthe",
            b"progno",
            b"synop",
            b"the",
        ] {
            let mut suffix = y.to_vec();
            suffix.extend_from_slice(b"ses");
            if w.ends_with(&suffix) {
                let mut r = w[..n - suffix.len()].to_vec();
                r.extend_from_slice(y);
                if y == b"analy" {
                    r.push(b'a');
                }
                r.extend_from_slice(b"sis");
                return r;
            }
        }

        // Rule 2: ends with "ies"
        if w.ends_with(b"ies") {
            if w.ends_with(b"quies") {
                let mut r = w[..n - 3].to_vec();
                r.push(b'y');
                return r;
            } else if n >= 4 && !matches!(w[n - 4], b'a' | b'e' | b'i' | b'o' | b'u' | b'y') {
                let mut r = w[..n - 3].to_vec();
                r.push(b'y');
                return r;
            }
            // else fall through
        }

        // Rule 3: ends with "ves", len>=4, byte at len-4 != 'f' -> "fe"
        if w.ends_with(b"ves") && n >= 4 && w[n - 4] != b'f' {
            let mut r = w[..n - 3].to_vec();
            r.extend_from_slice(b"fe");
            return r;
        }

        // Rule 4: ends with "ice", len>=4, byte at len-4 in {'m','|','l'} -> "ouse"
        if w.ends_with(b"ice") && n >= 4 && matches!(w[n - 4], b'm' | b'|' | b'l') {
            let mut r = w[..n - 3].to_vec();
            r.extend_from_slice(b"ouse");
            return r;
        }

        // Rule 5: ends with "a", len>=2, byte at len-2 in {'t','i'} -> "um"
        if w.ends_with(b"a") && n >= 2 && matches!(w[n - 2], b't' | b'i') {
            let mut r = w[..n - 1].to_vec();
            r.extend_from_slice(b"um");
            return r;
        }

        // Rule 6: "aliases"/"statuses" -> strip "es"
        for suf in [&b"aliases"[..], b"statuses"] {
            if w.ends_with(suf) {
                return w[..n - 2].to_vec();
            }
        }

        // Rule 7: "buses" -> strip "es"
        if w.ends_with(b"buses") {
            return w[..n - 2].to_vec();
        }

        // Rule 8: crises->crisis, axes->axis, testes->testis (replace "es" with "is")
        for suf in [&b"crises"[..], b"axes", b"testes"] {
            if w.ends_with(suf) {
                let mut r = w[..n - 2].to_vec();
                r.extend_from_slice(b"is");
                return r;
            }
        }

        // Rule 9: "matrices" -> replace "ices" with "ix"
        if w.ends_with(b"matrices") {
            let mut r = w[..n - 4].to_vec();
            r.extend_from_slice(b"ix");
            return r;
        }

        // Rule 10: "news" -> itself (stops processing)
        if w.ends_with(b"news") {
            return w.to_vec();
        }

        // Rule 11: "oes" -> strip "es"
        if w.ends_with(b"oes") {
            return w[..n - 2].to_vec();
        }

        // Rule 12: "octopi" -> "octopus"; "viri" -> "virus" (replace trailing "i" with "us")
        for suf in [&b"octopi"[..], b"viri"] {
            if w.ends_with(suf) {
                let mut r = w[..n - 1].to_vec();
                r.extend_from_slice(b"us");
                return r;
            }
        }

        // Rule 13: "quizzes" -> strip "zes"
        if w.ends_with(b"quizzes") {
            return w[..n - 3].to_vec();
        }

        // Rule 14: "vertices" -> "ex"; "indices" -> "ex" (replace "ices" with "ex")
        for suf in [&b"vertices"[..], b"indices"] {
            if w.ends_with(suf) {
                let mut r = w[..n - 4].to_vec();
                r.extend_from_slice(b"ex");
                return r;
            }
        }

        // Rule 15: xes/ches/sses/shes -> strip "es"
        for suf in [&b"xes"[..], b"ches", b"sses", b"shes"] {
            if w.ends_with(suf) {
                return w[..n - 2].to_vec();
            }
        }

        // Rule 16: ends with "s" -> strip one "s"
        if w.ends_with(b"s") {
            return w[..n - 1].to_vec();
        }

        // Rule 17: exactly "oxen" -> "ox"
        if w == b"oxen" {
            return b"ox".to_vec();
        }

        w.to_vec()
    }

    pub fn camelize(w: &[u8]) -> Vec<u8> {
        let mut r = Vec::with_capacity(w.len());
        for (i, seg) in w.split(|&b| b == b'_').enumerate() {
            if i == 0 {
                r.extend_from_slice(seg);
            } else if !seg.is_empty() {
                r.push(to_upper(seg[0]));
                r.extend_from_slice(&seg[1..]);
            }
        }
        r
    }

    pub fn camelize_upper(w: &[u8]) -> Vec<u8> {
        let mut r = Self::camelize(w);
        if !r.is_empty() {
            r[0] = to_upper(r[0]);
        }
        r
    }

    pub fn underscore(w: &[u8]) -> Vec<u8> {
        let mut r = Vec::with_capacity(w.len() + 4);
        for (i, &b) in w.iter().enumerate() {
            if b.is_ascii_uppercase() {
                if i > 0 {
                    r.push(b'_');
                }
                r.push(to_lower(b));
            } else {
                r.push(b);
            }
        }
        r
    }

    pub fn classify(w: &[u8]) -> Vec<u8> {
        Self::camelize_upper(&Self::singularize(w))
    }

    pub fn tableize(w: &[u8]) -> Vec<u8> {
        Self::pluralize(&Self::underscore(w))
    }

    pub fn humanize(w: &[u8]) -> Vec<u8> {
        let mut r: Vec<u8> = w.iter().map(|&b| if b == b'_' { b' ' } else { b }).collect();
        if !r.is_empty() {
            r[0] = to_upper(r[0]);
        }
        r
    }

    pub fn titleize(w: &[u8]) -> Vec<u8> {
        let mut r: Vec<u8> = w.iter().map(|&b| to_lower(b)).collect();
        for i in 0..r.len() {
            if r[i].is_ascii_lowercase() && (i == 0 || is_space(r[i - 1])) {
                r[i] = to_upper(r[i]);
            }
        }
        r
    }

    pub fn dasherize(w: &[u8]) -> Vec<u8> {
        w.iter().map(|&b| if b == b'_' { b'-' } else { b }).collect()
    }

    pub fn parameterize(w: &[u8]) -> Vec<u8> {
        let mut r = Vec::with_capacity(w.len());
        for &b in w {
            if b.is_ascii_alphanumeric() {
                r.push(to_lower(b));
            } else if b == b' ' {
                r.push(b'-');
            }
            // everything else deleted
        }
        while r.first() == Some(&b'-') {
            r.remove(0);
        }
        while r.last() == Some(&b'-') {
            r.pop();
        }
        r
    }

    pub fn upcase(w: &[u8]) -> Vec<u8> {
        w.iter().map(|&b| to_upper(b)).collect()
    }

    pub fn downcase(w: &[u8]) -> Vec<u8> {
        w.iter().map(|&b| to_lower(b)).collect()
    }

    pub fn capitalize(w: &[u8]) -> Vec<u8> {
        let mut r = Self::downcase(w);
        if !r.is_empty() {
            r[0] = to_upper(r[0]);
        }
        r
    }

    pub fn decapitalize(w: &[u8]) -> Vec<u8> {
        let mut r = w.to_vec();
        if !r.is_empty() {
            r[0] = to_lower(r[0]);
        }
        r
    }

    pub fn truncate(w: &[u8], n: usize) -> Vec<u8> {
        if w.len() > n {
            let keep = n - 3; // n=5 -> first 2 bytes + "..."
            let mut r = w[..keep].to_vec();
            r.extend_from_slice(b"...");
            r
        } else {
            w.to_vec()
        }
    }

    pub fn demodulize(s: &[u8]) -> Vec<u8> {
        let pos = s.iter().rposition(|&b| b == b':').map(|p| p + 2);
        match pos {
            Some(p) if p <= s.len() => s[p..].to_vec(),
            // Mirrors C++ std::out_of_range -> abort (SIGABRT) with no stdout.
            _ => std::process::abort(),
        }
    }

    pub fn is_plural(w: &[u8]) -> bool {
        Self::singularize(w) != w
    }

    pub fn is_singular(w: &[u8]) -> bool {
        Self::singularize(w) == w
    }
}

// Differential fuzz harness: compares /output/target/release/test20 against the
// reference binary on a large corpus, checking stdout bytes and exit status.
use std::process::Command;

const REF: &str = "/workspace/dataset/test20_executable";
const MINE: &str = "/output/target/release/test20";

fn run(bin: &str, args: &[Vec<u8>]) -> (Vec<u8>, i32) {
    use std::os::unix::ffi::OsStrExt;
    use std::os::unix::process::ExitStatusExt;
    let osargs: Vec<std::ffi::OsString> = args
        .iter()
        .map(|a| std::ffi::OsString::from_vec(a.clone()))
        .collect();
    let out = Command::new(bin).args(&osargs).output().unwrap();
    let code = match out.status.code() {
        Some(c) => c,
        None => -(out.status.signal().unwrap_or(0)),
    };
    (out.stdout, code)
}

fn check(args: &[Vec<u8>]) -> Result<(), String> {
    let (ao, arc) = run(REF, args);
    let (bo, brc) = run(MINE, args);
    let ok = if arc < 0 || brc < 0 {
        (arc < 0) == (brc < 0) && ao.is_empty() && bo.is_empty()
    } else {
        ao == bo && arc == brc
    };
    if ok {
        Ok(())
    } else {
        Err(format!(
            "args={:?}\n  ref  rc={} out={:?}\n  mine rc={} out={:?}",
            args.iter().map(|a| String::from_utf8_lossy(a).into_owned()).collect::<Vec<_>>(),
            arc,
            &ao[..ao.len().min(160)],
            brc,
            &bo[..bo.len().min(160)]
        ))
    }
}

// Simple xorshift PRNG for reproducibility.
struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    fn pick<'a>(&mut self, v: &'a [&'a [u8]]) -> &'a [u8] {
        v[(self.next() % v.len() as u64) as usize]
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

fn main() {
    let mut corpus: Vec<Vec<u8>> = Vec::new();

    let probes: &[&str] = &[
        "cherry", "bus", "quiz", "equipment", "information", "rice", "money", "species",
        "series", "fish", "sheep", "jeans", "police", "analyses", "bases", "diagnoses",
        "parentheses", "prognoses", "synopses", "theses", "parties", "Series", "movies", "yies",
        "eies", "leaves", "wives", "hives", "fves", "ffves", "mice", "lice", "|ice", "Police",
        "data", "via", "pizza", "aliases", "statuses", "buses", "abuses", "minibuses", "crises",
        "axes", "testes", "matrices", "news", "tomatoes", "shoes", "goes", "heroes", "octopi",
        "viri", "cacti", "quizzes", "xquizzes", "vertices", "indices", "boxes", "churches",
        "kisses", "dishes", "stomachaches", "waltzes", "cats", "gas", "class", "status", "s",
        "oxen", "aoxen", "oxenfoo", "oxens", "cat_dog", "a__b", "_foo", "foo_", "___", "fOO_bar",
        "CatDog", "CAT", "ABCd", "Foo_Bar", "Mixed_Case", "post_id", "person", "knife",
        "hello world!", " lead trail ", "1abc", "feet", "datum", "vium", "", ":", "x:", "x::",
        "a:b", "::", "a::b", "Test::x", " ", "  ", "\t", "\n", "\x0b", "\x0c", "\r", "a\tb c",
        "hello world", "caf\u{e9}", "\u{65e5}\u{672c}\u{8a9e}", "\u{1f389}\u{1f389}",
        "a\u{1f389}b", "!!!", "...", "-", "--", " - ", "a  b", "_", "__", "A_B", "sEs", "IES",
        "ies", "ves", "ice", "a", "A", "z", "SES", "News", "NEWS", "anewS", "octopI", "OCTOPI",
        "virI", "aliasES", "AliaseS", "BUSES", "matriceS", "quizez", "quizes", "vertice",
        "index", "mouse", "|", "||", "a|ice", "mICE", "lice_", "_lice", "ta", "ia", "tA", "iA",
        "xa", "aa", "quIeS", "moviES", "partIES", "i", "is", "as", "es", "us", "os", "ss",
        "xx", "xy",
    ];
    for p in probes {
        corpus.push(p.as_bytes().to_vec());
    }

    let mut rng = Rng(0x12345678);

    let alphabets: Vec<&[u8]> = vec![
        b"abcdefghijklmnopqrstuvwxyz",
        b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_",
        b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_ :.|-\t\n",
    ];
    for alpha in &alphabets {
        for _ in 0..1500 {
            let n = rng.below(16);
            let w: Vec<u8> = (0..n).map(|_| alpha[rng.below(alpha.len())]).collect();
            corpus.push(w);
        }
    }

    let suffixes: Vec<&[u8]> = vec![
        b"ies", b"ves", b"ses", b"es", b"s", b"ice", b"a", b"news", b"oxen", b"buses",
        b"aliases", b"quizzes", b"vertices", b"indices", b"matrices", b"octopi", b"viri",
        b"oes", b"xes", b"ches", b"sses", b"shes", b"crises", b"axes", b"testes", b"statuses",
        b"us", b"i", b"um",
    ];
    let prefixes: Vec<&[u8]> = vec![
        b"", b"a", b"qu", b"mov", b"part", b"di", b"l", b"m", b"|", b"x", b"ab", b"fo", b"ba",
        b"the", b"analy", b"her", b"tomat", b"g", b"sh", b"stomach", b"waltz", b"mini",
    ];
    let extras: Vec<&[u8]> = vec![b"", b"s", b"x", b"_", b":", b" "];
    let leadins: Vec<&[u8]> = vec![b"A_", b"_", b"Z", b"1", b" "];
    for _ in 0..2000 {
        let mut w = rng.pick(&prefixes).to_vec();
        w.extend_from_slice(rng.pick(&suffixes));
        if rng.next() % 10 < 4 {
            w.extend_from_slice(rng.pick(&extras));
        }
        if rng.next() % 10 < 3 {
            let mut v = rng.pick(&leadins).to_vec();
            v.extend_from_slice(&w);
            w = v;
        }
        corpus.push(w);
    }

    // non-ASCII words
    let npieces: Vec<&[u8]> = vec![
        "\u{e9}".as_bytes(), "\u{65e5}".as_bytes(), "\u{672c}".as_bytes(), "\u{8a9e}".as_bytes(),
        "\u{1f389}".as_bytes(), "\u{fc}".as_bytes(), "\u{f1}".as_bytes(), b"a", b"B", b"_", b" ",
        b":", b"\t",
    ];
    for _ in 0..400 {
        let n = 1 + rng.below(8);
        let mut w = Vec::new();
        for _ in 0..n {
            w.extend_from_slice(rng.pick(&npieces));
        }
        corpus.push(w);
    }

    // demodulize crash-path stress
    let crashalpha: &[u8] = b"ab:x_ ";
    for _ in 0..300 {
        let n = rng.below(7);
        let w: Vec<u8> = (0..n).map(|_| crashalpha[rng.below(crashalpha.len())]).collect();
        corpus.push(w);
    }

    corpus.sort();
    corpus.dedup();
    println!("corpus size: {}", corpus.len());

    let mut fails = 0usize;
    for (i, w) in corpus.iter().enumerate() {
        if let Err(msg) = check(std::slice::from_ref(w)) {
            fails += 1;
            if fails <= 15 {
                println!("MISMATCH {}", msg);
            }
        }
        if (i + 1) % 1000 == 0 {
            println!("  ...{}/{} checked, {} mismatches", i + 1, corpus.len(), fails);
        }
    }

    // no-arg and multi-arg cases
    let argcases: Vec<Vec<Vec<u8>>> = vec![
        vec![],
        vec![b"a".to_vec(), b"b".to_vec()],
        vec![b"word".to_vec(), b"extra1".to_vec(), b"extra2".to_vec()],
        vec![b"".to_vec(), b"x".to_vec()],
        vec![b":".to_vec(), b"ok".to_vec()],
    ];
    for args in &argcases {
        if let Err(msg) = check(args) {
            fails += 1;
            println!("ARGCASE MISMATCH {}", msg);
        }
    }
    println!("DONE. total mismatches: {}", fails);
    std::process::exit(if fails > 0 { 1 } else { 0 });
}

